'use strict';
const $=s=>document.querySelector(s), KEY='hanzi-forest-v1', DAY=86400000;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function initial(){return {version:1,records:{},custom:[],groups:{},settings:{round:24,newCount:6,lessonVersion:3,difficulty:'advanced',voice:'',audioMode:'fixed',rate:1,name:'小朋友'},sessions:[],read:[]}}
let state=initial(), storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw))}catch{storageOK=false}
function validate(s){if(!s||s.version!==1||!s.records||typeof s.records!=='object'||Array.isArray(s.records))throw Error('备份格式不正确');const clean=initial();clean.settings={...clean.settings,...s.settings};clean.settings.round=[6,8,10,12,16,24,32,48].includes(+clean.settings.round)?+clean.settings.round:24;clean.settings.newCount=Math.max(0,Math.min(8,+clean.settings.newCount||0));clean.settings.voice=String(clean.settings.voice||'');clean.settings.audioMode=clean.settings.audioMode==='device'?'device':'fixed';clean.settings.rate=[.85,1,1.1].includes(+clean.settings.rate)?+clean.settings.rate:1;if(s.settings?.lessonVersion!==3){clean.settings.round=24;clean.settings.newCount=6}clean.settings.lessonVersion=3;clean.settings.difficulty=['gentle','advanced'].includes(s.settings?.difficulty)?s.settings.difficulty:'advanced';clean.custom=Array.isArray(s.custom)?s.custom.filter(x=>x&&typeof x.char==='string'&&/^[\u3400-\u9fff]$/u.test(x.char)).map(x=>({char:x.char,pinyin:String(x.pinyin||''),word:String(x.word||x.char),sentence:String(x.sentence||''),emoji:'🌱',group:[0,1,2].includes(+x.group)?+x.group:1})):[];for(const [c,r]of Object.entries(s.records)){if(!/^[\u3400-\u9fff]$/u.test(c)||!r||typeof r!=='object')continue;clean.records[c]={level:Math.min(5,Math.max(0,+r.level||0)),seen:Math.max(0,+r.seen||0),miss:Math.max(0,+r.miss||0),due:Number.isFinite(+r.due)?+r.due:0,last:String(r.last||''),days:Array.isArray(r.days)?[...new Set(r.days.filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)))]:[],manual:!!r.manual,uncertain:!!r.uncertain};}for(const[c,g]of Object.entries(s.groups||{})){if(/^[\u3400-\u9fff]$/u.test(c)&&[0,1,2].includes(+g))clean.groups[c]=+g}clean.sessions=Array.isArray(s.sessions)?s.sessions.filter(x=>x&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Number.isFinite(x.count)).slice(-400):[];clean.read=Array.isArray(s.read)?s.read.filter(x=>STORIES.some(t=>t.id===x)):[];return clean}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('当前浏览器不能保存，请在家长页导出进度。')}}
const bank=()=>[...BASE.map(x=>({...x,...state.custom.find(y=>y.char===x.char)})),...state.custom.filter(x=>!BASE.some(y=>y.char===x.char))].map(x=>({...x,group:state.groups[x.char]??x.group}));
const get=c=>{const base=BASE.find(x=>x.char===c),custom=state.custom.find(x=>x.char===c);if(!base&&!custom)return;const x={...base,...custom};return {...x,group:state.groups[c]??x.group}};const record=c=>state.records[c]||{level:0,seen:0,miss:0,due:0,last:'',days:[],manual:false,uncertain:false};
function statusOf(c){const r=record(c);if(r.manual||r.days.length>=3&&r.level>=3)return 'mastered';if(r.uncertain||r.seen&&r.level===0)return 'weak';if(r.seen)return 'growing';if(get(c)?.group===0)return 'familiar';return 'unseen'}
const labels={mastered:'已掌握',weak:'再见几次',growing:'正在巩固',familiar:'已学过 · 待验证',unseen:'还没探索'};
const dueCards=()=>bank().filter(x=>record(x.char).seen&&record(x.char).due<=Date.now());
const stats=()=>{const b=bank();return {mastered:b.filter(x=>statusOf(x.char)==='mastered').length,weak:b.filter(x=>statusOf(x.char)==='weak').length,due:dueCards().length,today:state.sessions.filter(x=>x.date===today()).reduce((n,x)=>n+x.count,0),days:new Set(state.sessions.map(x=>x.date)).size}};
let route='home',filter='all',query='',session=null,story=null,cardParent=null,previousFocus=null;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
let currentAudio=null,playRequest=0;
function stopSpeech(){playRequest++;if(currentAudio){currentAudio.pause();currentAudio.remove();currentAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel()}
function isMandarin(v){return /^(zh[-_](CN|SG|Hans)([-_]|$)|cmn([-_]|$))/i.test(v.lang)}
function selectMandarin(voices,preferred){const choices=voices.filter(v=>isMandarin(v)&&v.localService!==false);return choices.find(v=>v.voiceURI===preferred)||choices.sort((a,b)=>voiceRank(b)-voiceRank(a))[0]||null}
function voiceRank(v){return (/zh[-_]CN/i.test(v.lang)?30:0)+(/premium|enhanced|natural|neural|高品质|增强/i.test(v.name)?20:0)+(/Tingting|Ting-Ting|Xiaoxiao|晓晓|Google.*普通话|Google.*Mandarin/i.test(v.name)?8:0)}
function speakDevice(text){if(!('speechSynthesis'in window)){toast('这台设备暂不支持系统朗读，内置词语可使用预置音频。');return}const voices=speechSynthesis.getVoices(),selected=selectMandarin(voices,state.settings.voice);if(!selected){toast('设备没有可用的普通话声音。内置词语可切换到“预置普通话音频”；例句和故事请在设备设置中添加普通话声音。');return}const u=new SpeechSynthesisUtterance(text);u.lang=selected.lang;u.voice=selected;u.rate=state.settings.rate;u.pitch=1;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('系统朗读未播放，请检查媒体音量或改用预置音频。')};speechSynthesis.speak(u)}
function speak(text){stopSpeech();const request=playRequest,sample=typeof FIXED_AUDIO!=='undefined'?FIXED_AUDIO[text]:null;if(state.settings.audioMode!=='device'&&sample){const clip=new Audio(sample.src);currentAudio=clip;clip.hidden=true;clip.dataset.source='fixed';document.body.append(clip);clip.playbackRate=state.settings.rate;clip.preservesPitch=true;clip.onended=()=>{clip.remove();if(currentAudio===clip)currentAudio=null};let fallbackUsed=false;const fallback=()=>{if(request!==playRequest||fallbackUsed)return;fallbackUsed=true;clip.remove();currentAudio=null;toast('这段预置音频未能播放，正在尝试设备普通话。');speakDevice(text)};clip.onerror=fallback;const playing=clip.play();if(playing&&playing.catch)playing.catch(fallback);return}speakDevice(text)}

function siteHeader(){return `<div class="topline"><div class="eyebrow">LITTLE STEPS, BIG DISCOVERIES</div><button class="profile" data-nav="parent" aria-label="打开家长设置"><span class="avatar">🧒</span> 我的小森林 <span style="color:#b2bba9">⌄</span></button></div>`}
function art(){return `<svg class="hero-art" viewBox="0 0 480 300" aria-hidden="true"><defs><linearGradient id="hill" x2="0" y2="1"><stop stop-color="#c4d5ab"/><stop offset="1" stop-color="#d5dfbe"/></linearGradient></defs><circle cx="350" cy="55" r="30" fill="#f8edc8"/><path d="M36 175Q130 93 218 169Q340 99 489 165V300H0Z" fill="#d8e3c8"/><path d="M0 242Q135 151 278 208Q377 151 480 194V300H0Z" fill="url(#hill)"/><path d="M219 300Q327 244 280 194" fill="none" stroke="#f1e9cb" stroke-width="34"/><g fill="#74946b"><path d="M383 75l-44 103h88z"/><path d="M422 117l-33 79h66z"/><path d="M95 135l-34 78h69z"/></g><g stroke="#7d8060" stroke-width="7"><path d="M383 164v65M421 186v40M95 203v29"/></g><g transform="translate(176 92) rotate(-8)"><rect width="82" height="101" rx="13" fill="#fffaf0" stroke="#c1cba8"/><path d="M8 50h66M41 9v83" stroke="#e8e7d4" stroke-dasharray="4 3"/><text x="41" y="72" text-anchor="middle" font-size="60" font-family="serif" fill="#66804e">木</text></g><g transform="translate(280 128) rotate(10)"><rect width="70" height="86" rx="11" fill="#fff8e9" stroke="#c1cba8"/><text x="35" y="61" text-anchor="middle" font-size="50" font-family="serif" fill="#ac8a55">林</text></g><g transform="translate(104 204)"><ellipse cx="28" cy="57" rx="43" ry="10" fill="#9db58c" opacity=".4"/><path d="M40 35Q100 4 75 57Q53 74 37 53Z" fill="#ce8550"/><path d="M74 30Q93 18 85 44L77 53Z" fill="#fff3de"/><ellipse cx="25" cy="42" rx="24" ry="29" fill="#d78c51"/><path d="M1 10L0-18L25 1L45-18L49 15Q47 41 25 43Q3 40 1 10Z" fill="#d78c51"/><path d="M4 10L24 26L45 9L42 31Q24 52 7 31Z" fill="#fff4df"/><circle cx="14" cy="13" r="2.6" fill="#384936"/><circle cx="36" cy="13" r="2.6" fill="#384936"/><ellipse cx="25" cy="27" rx="4" ry="3" fill="#384936"/><path d="M12 64v9M34 64v9" stroke="#78593d" stroke-width="6" stroke-linecap="round"/></g><g fill="#fff9da"><circle cx="53" cy="260" r="5"/><circle cx="370" cy="259" r="5"/><circle cx="448" cy="235" r="4"/></g><g fill="#75925b"><ellipse cx="52" cy="277" rx="7" ry="3" transform="rotate(-30 52 277)"/><ellipse cx="370" cy="275" rx="7" ry="3"/></g><path d="M115 53q8-11 16 0q8-11 16 0" fill="none" stroke="#8aa17a" stroke-width="2"/><g fill="#eef2e2"><ellipse cx="276" cy="47" rx="26" ry="9"/><ellipse cx="260" cy="42" rx="12" ry="9"/></g></svg>`}
function home(){const s=stats();const done=state.sessions.some(x=>x.date===today()&&x.completed);return `${siteHeader()}<div class="hello"><h1>欢迎来到汉字森林 <span style="font-size:24px">🌿</span></h1><p>和小狐狸一起，让每一个汉字都变成老朋友。</p></div><section class="hero"><div class="hero-content"><span class="pill">✧ ${state.settings.difficulty==='advanced'?'进阶探险':'基础巩固'} · 每轮 ${state.settings.round} 个字</span><h2>今天，去发现<br>汉字里的小世界。</h2><p>${done?'今天的小旅程已经完成。可以休息一下，再读个小故事。':state.settings.difficulty==='advanced'?'辨清相近的字，把词语和句子读明白。':'先找找熟悉的字，再认识一点点新朋友。'}</p><button class="primary" data-action="start">${done?'再玩一小轮':'开始今天的小旅程'} <span>→</span></button><span class="hero-note">${s.due?`${s.due} 个字在等你回来看看`:'不用赶路，按自己的节奏来'}</span></div>${art()}</section><div class="stats"><div class="stat"><span class="stat-icon">🌱</span><div><strong>${s.mastered}</strong><span class="unit">个</span><small>已经熟悉的字朋友</small></div></div><div class="stat"><span class="stat-icon">🍃</span><div><strong>${s.due}</strong><span class="unit">个</span><small>今天该见面的老朋友</small></div></div><div class="stat"><span class="stat-icon">☀️</span><div><strong>${s.days}</strong><span class="unit">天</span><small>来森林探索的日子</small></div></div></div><div class="section-head"><h2>沿着小路，去探索</h2><button class="text-link" data-nav="parent">按自己的节奏设置 ↗</button></div><section class="activity-grid"><button class="activity" data-action="start-review"><span class="number">01 / REVISIT</span><span class="activity-icon">🔎</span><h3>找找字朋友</h3><p>那些眼熟又有点拿不准的字，<br>换个地方，再见一面。</p><div class="activity-footer"><span>查漏补缺 · 温柔复习</span><span class="arrow">→</span></div></button><button class="activity" data-nav="cards"><span class="number">02 / DISCOVER</span><span class="activity-icon" style="font-family:var(--serif)">林</span><h3>汉字小发现</h3><p>看看字形，听听词语，<br>发现汉字之间的小秘密。</p><div class="activity-footer"><span>字 → 词 → 句</span><span class="arrow">→</span></div></button><button class="activity" data-nav="stories"><span class="number">03 / READ</span><span class="activity-icon">📖</span><h3>故事小屋</h3><p>把认识的字放进小故事，<br>和爸爸妈妈一起读一读。</p><div class="activity-footer"><span>原创故事 · 亲子共读</span><span class="arrow">→</span></div></button></section><div class="bottom-strip"><div class="little-letter"><div class="letter-art">明</div><div><strong>汉字里，也藏着小发现</strong><p>“日”和“月”手拉手，变成明亮的“明”。</p></div></div><div class="today-words"><div><strong>从身边开始认字</strong><p>把汉字带进生活里</p></div><div class="mini-tiles">${['海','沙','贝'].map(c=>`<button class="mini-tile" data-card="${c}">${c}</button>`).join('')}</div></div></div><footer>一片叶子，一段故事，一点点长大。</footer>`}
function cards(){let list=bank().filter(x=>(!query||[x.char,x.word,x.pinyin].some(v=>v.includes(query)))&&(filter==='all'||filter==='review'&&x.group===1||filter==='new'&&x.group===2||filter==='weak'&&statusOf(x.char)==='weak'||filter==='mastered'&&statusOf(x.char)==='mastered'));return `${siteHeader()}<h1>我的字卡</h1><p class="page-intro">点一个汉字，听词语、读句子。字卡里的图片只帮助理解，复习时会藏起来。</p><input class="search" id="search" placeholder="找一个字、词语或拼音…" aria-label="搜索字卡" value="${esc(query)}"><div class="chips">${[['all','全部字朋友'],['review','查漏候选'],['new','探索候选'],['weak','再见几次'],['mastered','已经掌握']].map(([k,v])=>`<button class="chip ${filter===k?'active':''}" data-filter="${k}">${v}</button>`).join('')}</div><div class="table-info" style="margin-bottom:16px">共 ${list.length} 个字 · 内置组别是练习分组，家长可按教材调整。</div><div class="char-grid">${list.map(x=>`<button class="char-tile" data-card="${x.char}"><b>${x.char}</b><small><span class="dot" style="background:${statusOf(x.char)==='mastered'?'#547b49':statusOf(x.char)==='weak'?'#dba569':'#bbc8ae'}"></span>${labels[statusOf(x.char)]}</small></button>`).join('')}</div>${list.length?'':'<div class="empty">这里暂时没有字朋友，换个分组看看吧。</div>'}`}
function stories(){return `${siteHeader()}<h1>故事小屋</h1><p class="page-intro">先自己试着读，再请大人帮忙。先读新的进阶故事，找找原因和先后顺序。点不认识的字可以听读。</p><div class="story-grid" style="margin-top:28px">${STORIES.map(x=>`<button class="story-card" data-story="${x.id}"><div class="story-cover" style="background:${x.color}">${x.emoji}</div><h3>${x.title}</h3><p>${x.label} · 亲子共读${state.read.includes(x.id)?' · 已读过 ✓':''}</p></button>`).join('')}</div><div class="panel" style="margin-top:25px"><h2>把发现带到屏幕外</h2><p class="muted">读完“送给大海的礼物”，可以一起找找路牌上的“海”，再用自己的话说一说今天看到了什么。无需每个字都认识，也不用一边读一边考试。</p></div>`}
function garden(){const s=stats(),items=[['🌱','第一颗小种子','完成一次小旅程',state.sessions.some(x=>x.completed)],['🌿','嫩绿的小芽','在 3 个不同日子来探索',s.days>=3],['🌼','第一朵小花','掌握 10 个字朋友',s.mastered>=10],['🌳','自己的小树林','掌握 30 个字朋友',s.mastered>=30],['🐚','海边的故事','读完海边故事',state.read.includes('sea')],['🌙','晚安月亮','读完月亮故事',state.read.includes('moon')],['📚','故事收藏家','读完 3 个原创故事',state.read.length>=3],['🦊','小狐狸的朋友','在 7 个不同日子来探索',s.days>=7]];return `${siteHeader()}<h1>成长花园</h1><p class="page-intro">每一次尝试，都在悄悄发芽。答错不会扣掉小种子，休息几天也不会失去它们。</p><div class="garden" style="margin-top:28px">${items.map(([e,t,d,on])=>`<div class="plant ${on?'':'locked'}"><div class="emoji">${on?e:'🌰'}</div><h3>${t}${on?' ✓':''}</h3><p>${d}</p></div>`).join('')}</div><div class="panel" style="margin-top:25px"><h2>已经一起走过 ${s.days} 天</h2><p class="muted">${s.mastered} 个字已掌握，${s.weak} 个字需要多见几次，${state.read.length} 个故事留下了回忆。</p><p class="note">“已掌握”需要在至少 3 个不同日子独立答对，或由家长确认。一次选对不会直接算掌握。</p></div>`}
function parent(){const s=stats();return `${siteHeader()}<h1>家长小天地</h1><p class="page-intro">根据孩子的实际状态调整，循序渐进地复习和拓展。</p>${!storageOK?'<div class="warning">当前浏览器的保存功能不可用，请及时导出进度。</div>':''}<div class="parent-grid" style="margin-top:25px"><div><section class="panel"><h2>今天玩多少？</h2><label>学习难度<select id="difficulty"><option value="advanced" ${state.settings.difficulty==='advanced'?'selected':''}>进阶探险 · 形近字、组词、读句子</option><option value="gentle" ${state.settings.difficulty==='gentle'?'selected':''}>基础巩固 · 熟字复习与听词找字</option></select></label><p class="note">进阶模式优先常用阅读字与易混字；基础字仅在不熟时回顾。组词、句子填空先自己读，答完再听完整句子。</p><label>每轮题量<select id="round">${[6,8,10,12,16,24,32,48].map(n=>`<option value="${n}" ${state.settings.round===n?'selected':''}>${n} 个字${n===24?' · 推荐':''}</option>`).join('')}</select></label><label>每轮最多探索几个新字<select id="newCount">${[0,1,2,3,4,6,8].map(n=>`<option value="${n}" ${state.settings.newCount===n?'selected':''}>${n===0?'0 个 · 只复习':n+' 个'}</option>`).join('')}</select></label><button class="primary" data-action="save-settings">保存节奏</button><p class="note">每轮默认 24 道认字题，另有新字介绍和必要的错题回顾。每题 4 个选项。答错会解释并亮出正确答案，隔至少 2 题再来一次；同字当轮最多追加 2 次，仍不熟的留到下一轮优先复习。每轮结束可以休息，没有倒计时。</p></section><section class="panel"><h2>对齐家里的教材</h2><p class="note">可按实际教材或学习目标添加汉字。内置 ${BASE.length} 字为原创练习候选，不对应特定教材分册。</p><label>把实际学到的汉字粘贴在这里<textarea id="chars" placeholder="例如：海 沙 贝 船 浪\n自动去掉标点、空格和重复字"></textarea></label><label>这些字目前的状态<select id="assign"><option value="weak">还不稳，优先复习</option><option value="review">学过，先查漏</option><option value="known">家长确认已掌握</option><option value="new">正在学 / 新探索</option></select></label><button class="secondary" data-action="assign">更新这组汉字</button><p class="note">不在内置字库的汉字也能加入、听读和练习。可在字卡里补充常用词与例句；多音字请用教材中的词语练读。</p></section></div><div><section class="panel"><h2>普通话朗读</h2><label>朗读方式<select id="audio-mode"><option value="fixed" ${state.settings.audioMode==='fixed'?'selected':''}>预置普通话音频 · 推荐</option><option value="device" ${state.settings.audioMode==='device'?'selected':''}>设备普通话声音 · 备用</option></select></label><label>朗读节奏<select id="audio-rate"><option value=".85" ${state.settings.rate===.85?'selected':''}>慢一点</option><option value="1" ${state.settings.rate===1?'selected':''}>自然节奏 · 推荐</option><option value="1.1" ${state.settings.rate===1.1?'selected':''}>稍快一点</option></select></label><label>备用的设备普通话声音<select id="voice"><option value="">自动选择本地普通话声音</option>${('speechSynthesis'in window?speechSynthesis.getVoices():[]).filter(v=>isMandarin(v)&&v.localService!==false).map(v=>`<option value="${esc(v.voiceURI)}" ${state.settings.voice===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('')}</select></label><div class="actions"><button class="secondary" data-action="voice-test">试听整句“小鱼在水里游。”</button><button class="secondary" data-action="voice-save">保存声音</button><button class="quiet" data-action="stop-audio">停止朗读</button></div><p class="note">内置词语、原创例句和小动物故事均优先播放固定音频。自填内容仍使用设备本地普通话声音，不会自动上传。多音字放在词语或原句里读。词语音频来自有道及 Google；原创例句、故事使用 Google 普通话整句音频。无需麦克风；没有声音时先检查媒体音量。口头认读仍由陪伴的大人确认。</p></section><section class="panel"><h2>学习记录</h2><div class="table-info">已掌握 ${s.mastered} 字 · 待复习 ${s.due} 字 · 不稳 ${s.weak} 字</div><p class="note">进度保存在当前浏览器，换设备、清理浏览器或使用无痕模式不会同步。换设备前导出，再在新设备导入。</p><div class="actions"><button class="secondary" data-action="export">导出进度备份</button><button class="secondary" data-action="import">导入备份</button><input hidden type="file" id="import-file" accept="application/json,.json"></div></section><section class="panel"><h2>这片森林怎么教？</h2><p class="note">① 先无图认字：避免靠图片猜答案。<br>② 字词句相连：字卡给词语和原创例句，故事里再见一面。<br>③ 变换练法：口头认读、听词找字、词句填空交替。<br>④ 间隔复习：独立答对后约 1、3、7、14、30 天再见，答错回到短间隔。这个时间表是产品规则，不是对单个孩子的记忆预测。<br>⑤ 适度看字形：比较部件与近形字；记忆提示不作为字源解释。<br>⑥ 兴趣优先：每天短时、亲子陪伴，没有排名和倒计时。</p><div class="source-links">参考：<a href="https://www.pep.com.cn/bks/xxyw/jzjd/202512/t20251202_2004552.shtml" target="_blank" rel="noopener">人教社《低年级识字教学的几点建议》↗</a><br><a href="https://www.moe.gov.cn/moe_879/moe_1252/s6047/s6073/201201/t20120112_129330.html" target="_blank" rel="noopener">教育部：在家里如何开展早期阅读 ↗</a></div></section></div></div>`}
function render(){const f={home,cards,stories,garden,parent};$('#main').innerHTML=f[route]();document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===route));}
function navigate(p){route=p;closeModal();render();window.scrollTo(0,0)}
function showModal(html,wide=false){if(!$('#overlay').children.length)previousFocus=document.activeElement;$('#overlay').innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="汉字森林活动">${html}</section>`;document.body.style.overflow='hidden';$('#overlay button')?.focus()}
function closeModal(){stopSpeech();$('#overlay').innerHTML='';document.body.style.overflow='';session=null;story=null;cardParent=null;previousFocus?.focus?.()}
const modalHead=(label,action='close')=>`<div class="modal-head"><span>${label}</span><button class="close" data-action="${action}" aria-label="关闭">×</button></div>`;
function detail(c){const x=get(c);if(!x){speak(c);toast(`“${c}”暂未加入字库，可以请大人讲一讲。`);return}const r=record(c);showModal(`${modalHead('汉字小发现',cardParent?'back-story':'close')}<div class="question">${semanticVisual(x)}<div class="pinyin">${esc(x.pinyin||'一起听一听')}</div><div class="big-char">${x.char}</div><div class="wordline">${esc(x.word)}</div><button class="audio" data-speak="${esc(x.word)}">♪ 听词语</button><p class="sentenceline">${esc(x.sentence||'请和爸爸妈妈一起，用这个字说一个词语。')}</p>${x.sentence?`<button class="quiet" data-speak="${esc(x.sentence)}">听完整句子 →</button>`:''}${HINTS[c]?`<div class="hint-box">字形小提示：${HINTS[c]}<br><small>帮助观察字形，不作字源解释。</small></div>`:''}<p class="detail-status">${labels[statusOf(c)]} · 在 ${r.days.length} 个不同日子独立答对</p><div class="actions" style="justify-content:center"><button class="secondary" data-mark="${c}">这个字还不稳</button><button class="secondary" data-edit="${c}">家长补充词句</button></div></div>`)}
function updateRecord(c,ok){const r={...record(c),days:[...record(c).days]};r.seen++;r.last=today();if(ok){if(!r.days.includes(today())){r.days.push(today());r.level=Math.min(5,r.level+1)}r.uncertain=false;r.due=Date.now()+([1,1,3,7,14,30][r.level])*DAY;}else{r.level=0;r.miss++;r.manual=false;r.uncertain=true;r.due=Date.now()+DAY;}state.records[c]=r;save()}
function task(x,i){if(state.settings.difficulty==='advanced'&&i%3===0&&WORD_ITEMS[x.char])return {char:x.char,type:'word',retry:false};return {char:x.char,type:i%2&&x.sentence&&x.sentence.includes(x.char)?'context':'listen',retry:false}}
function start(review=false){const n=state.settings.round,all=bank(),advanced=state.settings.difficulty==='advanced',eligible=x=>!advanced||x.group>0||statusOf(x.char)==='weak';const due=shuffle(dueCards().filter(eligible)).sort((a,b)=>record(a.char).due-record(b.char).due);const weak=shuffle(all.filter(x=>statusOf(x.char)==='weak'&&!due.some(d=>d.char===x.char)));const candidates=shuffle(all.filter(x=>!record(x.char).seen&&(advanced?!x.advanced&&(x.group===2||WORD_ITEMS[x.char]):x.group===1))).sort((a,b)=>advanced?Number(!!WORD_ITEMS[b.char])-Number(!!WORD_ITEMS[a.char]):0);const familiar=shuffle(all.filter(x=>!record(x.char).seen&&(advanced?x.group===1&&!WORD_ITEMS[x.char]:x.group===0)));const resting=shuffle(all.filter(x=>record(x.char).seen&&eligible(x)&&!due.some(d=>d.char===x.char)&&!weak.some(d=>d.char===x.char)));const freshPool=shuffle(all.filter(x=>!record(x.char).seen&&(advanced?x.advanced:x.group===2&&!x.advanced)));const newItems=review?[]:freshPool.slice(0,state.settings.newCount);const selected=new Set(newItems.map(x=>x.char));const oldPool=[...weak,...due,...candidates,...familiar,...resting].filter((x,i,a)=>!selected.has(x.char)&&a.findIndex(y=>y.char===x.char)===i);const old=oldPool.slice(0,n-newItems.length);const q=newItems.map(x=>({char:x.char,type:'teach'}));let added=0;old.forEach((x,i)=>{q.push(task(x,i));if(added<newItems.length&&(i+1)>=Math.ceil((added+1)*old.length/newItems.length)){const fresh=newItems[added++];q.push({char:fresh.char,type:advanced&&WORD_ITEMS[fresh.char]?'word':fresh.sentence?'context':'listen'})}});while(added<newItems.length){const fresh=newItems[added++];q.push({char:fresh.char,type:advanced&&WORD_ITEMS[fresh.char]?'word':fresh.sentence?'context':'listen'})}session={queue:q,index:0,solved:0,helped:0,answered:false,hinted:false,results:[],retries:new Map(),saved:false};if(!q.length){toast('暂时没有可练习的字，请在家长页添加。');session=null;return}renderTask()}
function optionsFor(c){const word=get(c)?.word||c;const near=state.settings.difficulty==='advanced'?NEAR_GROUPS.filter(group=>group.includes(c)).flatMap(group=>[...group]):[];const others=[...shuffle([...new Set(near)]),...shuffle(bank().filter(x=>x.char!==c).map(x=>x.char))];return shuffle([c,...[...new Set(others)].filter(x=>x!==c&&!word.includes(x)).slice(0,3)])}

function renderTask(){if(!session)return;if(session.index>=session.queue.length){finish();return}const t=session.queue[session.index],x=get(t.char);session.answered=false;session.hinted=false;let content='';if(t.type==='teach'){content=`<h2>认识一个新朋友</h2><p class="instruction">先看字，再听听它住在哪个词语里。</p>${semanticVisual(x)}<div class="pinyin">${esc(x.pinyin)}</div><div class="big-char">${x.char}</div><div class="wordline">${esc(x.word)}</div><p class="sentenceline">${esc(x.sentence||'和大人一起，说一个有这个字的词语。')}</p><button class="audio" data-speak="${esc(x.word)}">♪ 听词语</button>${HINTS[x.char]?`<div class="hint-box">看字形：${HINTS[x.char]}</div>`:''}<div class="actions" style="justify-content:center"><button class="primary" data-action="teach-next">记住啦，继续走 →</button></div>` }else if(t.type==='word'){const item=WORD_ITEMS[x.char];content=`<h2>${t.retry?'再来认一次：':''}把词语补完整</h2><p class="instruction">先自己读一读，注意形状相近的字。</p><div class="word-puzzle">${esc(item.phrase).replace('＿','<span class="word-blank">＿</span>')}</div><div class="choices four-choices">${shuffle(item.options).map(c=>`<button class="choice" data-answer="${c}">${c}</button>`).join('')}</div><button class="quiet" data-action="hint">还不确定，给我一点提示</button><div id="task-hint"></div>`}else if(t.type==='recall'){content=`<h2>${t.retry?'再见一次，试试看':'这个字，你认识吗？'}</h2><p class="instruction">先自己读一读。请大人听听，再一起选。</p><div class="big-char">${x.char}</div><div class="self-actions"><button class="secondary" data-action="recall-help">还不太确定</button><button class="primary" data-action="recall-ok">我读出来了 ✓</button></div><p class="note">先不出声提示，也不看图片。独立认读才算掌握。</p>`}else{const context=t.type==='context';content=`<h2>${t.retry?'再来认一次：':''}${context?'把字送回句子里':'听一听，找找字'}</h2><p class="instruction">${context?'读读句子，选一个合适的字。':'点小喇叭，听词语，再从 4 个字里选出听到的字。'}</p>${context?`<p class="sentenceline">${esc(x.sentence).replaceAll(x.char,'<mark style="background:#e4edce;padding:0 9px;border-radius:5px">＿</mark>')}</p>`:`<div class="listen-cue" aria-hidden="true">♪<span>听清词语，再找字</span></div>`}${!context||state.settings.difficulty==='gentle'?`<button class="audio" data-action="task-audio">♪ ${context?'听完整句子':'听词语'}</button>`:'<p class="note">先读句子再选择，答完可以听完整句子。</p>'}<div class="choices four-choices">${optionsFor(x.char).map(c=>`<button class="choice" data-answer="${c}">${c}</button>`).join('')}</div><button class="quiet" data-action="hint">还不确定，给我一点提示</button><div id="task-hint"></div>`}showModal(`${modalHead(`森林小旅程 · 第 ${session.index+1} 步 / 共 ${session.queue.length} 步`,'exit-session')}<div class="progress-track"><div class="progress-fill" style="width:${session.index/session.queue.length*100}%"></div></div><div class="question">${content}</div><div id="feedback" aria-live="polite"></div>`)}
function enqueueRetry(t){const count=session.retries.get(t.char)||0;if(count>=2)return false;session.retries.set(t.char,count+1);const position=session.index+3;const fillers=shuffle(bank().filter(x=>x.char!==t.char&&(state.settings.difficulty==='advanced'?(x.group>0||record(x.char).uncertain):(x.group===0||record(x.char).seen))));while(session.queue.length<position){const x=fillers.pop();if(!x)break;session.queue.push({...task(x,session.queue.length),filler:true})}session.queue.splice(Math.min(position,session.queue.length),0,{char:t.char,type:state.settings.difficulty==='advanced'&&WORD_ITEMS[t.char]&&t.type!=='word'?'word':t.type==='word'?'context':t.type==='context'?'listen':get(t.char).sentence?'context':'listen',retry:true});return true}
function answer(ok,chosen){if(!session||session.answered)return;session.answered=true;const t=session.queue[session.index],x=get(t.char),success=ok&&!session.hinted,independent=success&&!t.retry;let scheduled=false;session.solved+=independent?1:0;if(!success)session.helped++;if(!t.retry){updateRecord(t.char,independent);session.results.push(t.char)}else if(!success){updateRecord(t.char,false)}if(!success)scheduled=enqueueRetry(t);document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(b.dataset.answer===t.char)b.classList.add('correct');else if(b.dataset.answer===chosen)b.classList.add('wrong')});document.querySelectorAll('[data-action^="recall-"]').forEach(b=>b.disabled=true);const heading=success?(t.retry?'这次找对啦！下次我们再见一面。':'找对啦，真棒！'):ok?'有提示也没关系，再独立试试。':'没关系，正确的字是“'+t.char+'”。';const note=success?'':scheduled?'隔两题，我们再来认一次。':'这个字已经记入复习，下轮优先再见。';$('#feedback').innerHTML=`<div class="feedback ${success?'':'warm'}"><p><strong>${heading}</strong><br><span style="font-size:23px;font-family:var(--serif)">${x.char}</span> ${esc(x.pinyin)} · ${esc(x.word)}<br>${esc(x.sentence||'和大人一起用这个字说个词语吧。')}</p>${note?`<p class="retry-note">${note}</p>`:''}<div class="actions"><button class="audio" data-speak="${esc(x.word)}">♪ 再听词语</button>${x.sentence?`<button class="audio" data-speak="${esc(x.sentence)}">♪ 听句子</button>`:''}</div><button class="primary" data-action="next">${session.index+1<session.queue.length?'继续走 →':'看看今天的小收获 →'}</button></div>`;$('#feedback').scrollIntoView({block:'nearest',behavior:'smooth'})}

function persistSession(){if(session&&!session.saved&&session.results.length){state.sessions.push({date:today(),count:new Set(session.results).size,independent:session.solved,completed:session.index>=session.queue.length});session.saved=true;save()}}
function finish(){persistSession();showModal(`${modalHead('今天的小收获')}<div class="finished"><div class="trophy">🌱</div><h2>小森林，又长大了一点！</h2><p>今天和 ${new Set(session.results).size} 个字朋友见了面。<br>${session.helped?'有些字还需要多见几次，小狐狸已经记下啦。':'每一次认真尝试，都值得一颗小种子。'}</p><div class="mini-tiles" style="justify-content:center;margin:25px 0;flex-wrap:wrap">${[...new Set(session.results)].map(c=>`<span class="mini-tile">${c}</span>`).join('')}</div><p>现在，看看远处，喝口水。<br>也可以到生活里，找找这些字。</p><button class="primary" data-action="finish-home">收好小种子，回森林 →</button></div>`);render()}
function openStory(id){story={id,page:0,answers:0};renderStory()}
function renderStory(){const x=STORIES.find(x=>x.id===story.id);const q=x.questions[story.page];showModal(`${modalHead(x.label)}<h2 style="text-align:center;font-family:var(--serif);margin:15px 0 25px">${x.emoji} ${x.title}</h2><div class="reading">${x.lines.map(line=>`<p>${[...line].map(c=>/[\u3400-\u9fff]/.test(c)?`<button data-read-char="${c}" data-read-line="${esc(line)}" aria-label="听“${c}”所在的句子">${c}</button>`:esc(c)).join('')}</p>`).join('')}</div><button class="audio" data-speak="${esc(x.lines.join(''))}">♪ 听完整故事</button><p class="note">先试着读，再听；点字会读它所在的原句，帮助听清多音字。点读不计为独立掌握。</p>${q?`<div class="hint-box"><strong>聊一聊：${q.q}</strong><div class="choices ${q.opts.length===4?'reading-choices':''}" style="margin:15px 0 0">${q.opts.map((o,i)=>`<button class="choice word-choice" data-story-answer="${i}">${o}</button>`).join('')}</div><div id="story-feedback" aria-live="polite"></div></div>`:`<div class="feedback">故事读完啦！你最喜欢哪一句？和爸爸妈妈说一说。<button class="primary" data-action="story-done">收好故事，回小屋 →</button></div>`}`,true)}
function editCard(c){const x=get(c);showModal(`${modalHead('家长补充词句')}<h2>给“${c}”补充一个生活里的例子</h2><label>拼音（可选，注意多音字）<input class="search" id="edit-pinyin" value="${esc(x.pinyin)}"></label><label>常用词（须包含这个字）<input class="search" id="edit-word" value="${esc(x.word)}"></label><label>例句（须包含这个字）<textarea id="edit-sentence">${esc(x.sentence)}</textarea></label><button class="primary" data-save-card="${c}">保存词句</button>`)}
// Custom entries may override rich entries for parent-provided textbook contexts.

function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`汉字森林-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(d.nav){e.preventDefault();navigate(d.nav);return}if(d.card){cardParent=null;detail(d.card);return}if(d.filter){filter=d.filter;render();return}if(d.story){openStory(d.story);return}if(d.speak){speak(d.speak);return}if(d.answer){answer(d.answer===session.queue[session.index].char,d.answer);return}if(d.mark){const r=record(d.mark);state.records[d.mark]={...r,manual:false,uncertain:true,level:0,due:Date.now(),seen:Math.max(1,r.seen)};save();detail(d.mark);toast('记下来啦，下次优先和它见面。');return}if(d.edit){editCard(d.edit);return}if(d.saveCard){const c=d.saveCard,word=$('#edit-word').value.trim(),sentence=$('#edit-sentence').value.trim(),pinyin=$('#edit-pinyin').value.trim();if(!word.includes(c)||sentence&&!sentence.includes(c)){toast('词语和例句都需要包含“'+c+'”。');return}const x=get(c);state.custom=state.custom.filter(x=>x.char!==c);state.custom.push({...x,word,sentence,pinyin});save();detail(c);toast('词句已保存。');return}if(d.readChar){speak(d.readLine||get(d.readChar)?.word||d.readChar);document.querySelectorAll('.reading button').forEach(el=>el.classList.toggle('reading-current',el.dataset.readLine===d.readLine&&el.dataset.readChar===d.readChar));toast('正在读这个字所在的句子。');return}if(d.storyAnswer!==undefined){const x=STORIES.find(x=>x.id===story.id),q=x.questions[story.page];if(+d.storyAnswer===q.answer){document.querySelectorAll('[data-story-answer]').forEach(b=>b.disabled=true);$('#story-feedback').innerHTML='<p style="margin-top:15px">你读懂啦！</p><button class="secondary" data-action="story-next">继续聊一聊 →</button>'}else{$('#story-feedback').textContent='再回到故事里找一找，不着急。'}return}switch(d.action){case 'start':start();break;case 'start-review':start(true);break;case 'close':closeModal();render();break;case 'exit-session':if(session&&session.results.length){persistSession();toast('已完成的练习保存了，休息一下吧。')}closeModal();render();break;case 'finish-home':navigate('home');break;case 'teach-next':session.index++;renderTask();break;case 'next':session.index++;renderTask();break;case 'recall-ok':answer(true);break;case 'recall-help':answer(false);break;case 'task-audio':{const t=session.queue[session.index],x=get(t.char);speak(t.type==='context'?x.sentence:x.word);break}case 'hint':{if(session.answered)break;session.hinted=true;const x=get(session.queue[session.index].char);$('#task-hint').innerHTML=`<div class="hint-box">${esc(x.word)} · ${esc(x.pinyin)}<br>${esc(HINTS[x.char]||'看一看字形，和大人一起说说这个词是什么意思。')}</div>`;break}case 'back-story':story=cardParent;cardParent=null;renderStory();break;case 'story-next':story.page++;renderStory();break;case 'story-done':if(!state.read.includes(story.id)){state.read.push(story.id);save()}navigate('stories');break;case 'save-settings':state.settings.difficulty=$('#difficulty').value;state.settings.round=+$('#round').value;state.settings.newCount=+$('#newCount').value;save();toast('节奏保存好了。');break;case 'voice-test':{const prev={...state.settings};state.settings.voice=$('#voice').value;state.settings.audioMode=$('#audio-mode').value;state.settings.rate=+$('#audio-rate').value;speak('小鱼在水里游。');state.settings=prev;break}case 'stop-audio':stopSpeech();break;case 'voice-save':state.settings.voice=$('#voice').value;state.settings.audioMode=$('#audio-mode').value;state.settings.rate=+$('#audio-rate').value;save();toast('朗读方式和节奏已保存。');break;case 'export':exportData();break;case 'import':$('#import-file').click();break;case 'assign':{const chars=[...new Set([...$('#chars').value].filter(c=>/^[\u3400-\u9fff]$/u.test(c)))],mode=$('#assign').value;if(!chars.length){toast('先填入实际学到的汉字。');break}for(const c of chars){if(!get(c))state.custom.push({char:c,pinyin:'',word:c,sentence:'',emoji:'🌱',group:mode==='new'?2:1});state.groups[c]=mode==='new'?2:1;const r={...record(c),days:[...record(c).days]};if(mode==='known'){r.manual=true;r.uncertain=false;r.level=3;r.seen=Math.max(1,r.seen);r.due=Date.now()+14*DAY}else if(mode==='weak'){r.manual=false;r.uncertain=true;r.level=0;r.seen=Math.max(1,r.seen);r.due=Date.now()}else if(mode==='new'){r.manual=false;r.uncertain=false;r.level=0;r.seen=0;r.days=[];r.due=0}else{r.manual=false;r.uncertain=false;r.level=0;r.seen=Math.max(1,r.seen);r.due=Date.now()}state.records[c]=r}save();render();toast(`已更新 ${chars.length} 个汉字。`);break}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>2000000)throw Error('文件过大');const incoming=validate(JSON.parse(await file.text()));if(!confirm('导入会替换当前设备上的学习记录。确定导入吗？建议先导出当前进度。'))return;state=incoming;save();render();toast('进度导入成功。')}catch(err){toast('未能导入：'+err.message)}}});
document.addEventListener('keydown',e=>{if(!$('#overlay').children.length)return;if(e.key==='Escape'){if(session)persistSession();closeModal();render()}if(e.key==='Tab'){const nodes=[...$('#overlay').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')],first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('beforeunload',()=>{if(session)persistSession()});
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',()=>{if(route==='parent'&&!$('#overlay').children.length)render()});
render();
